#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n;        cin >> n;         vector<ll> a(n);        for (auto &x : a) cin >> x;         // Check if already not sorted        bool sorted = true;        for (int i = 0; i + 1 < n; i++) {            if (a[i] > a[i + 1]) {                sorted = false;                break;            }        }         if (!sorted) {            cout << 0 << "\n";            continue;        }         ll ans = LLONG_MAX;        for (int i = 0; i + 1 < n; i++) {            ll gap = a[i + 1] - a[i];            ll ops = gap / 2 + 1;            ans = min(ans, ops);        }         cout << ans << "\n";    }    return 0;}